1	package zkcircuit
2	
3	import (
4		"errors"
5		"os"
6		"path/filepath"
7		"strings"
8		"testing"
9	)
10	
11	// Relative data-directory pinning. Once Open("bench-data") succeeds the
12	// directory is fixed for the store's lifetime; a later process working
13	// directory change must never move reads, writes, the lock, artifact/job
14	// bindings or Dir onto another bench-data.
15	
16	const altDef = `{"modulus":"11","constraints":[
17			{"a":[{"wire":1,"coeff":"1"}],"b":[{"wire":2,"coeff":"1"}],"c":[{"wire":0,"coeff":"10"}]}]}`
18	
19	// seedBenchData creates and closes a fully populated bench-data store at the
20	// given absolute directory (no chdir involved): one frozen, setup-registered
21	// and compiled circuit "c" v1 carrying desc, built from def.
22	func seedBenchData(t *testing.T, absDir, desc, def string) Artifact {
23		t.Helper()
24		if err := os.MkdirAll(absDir, 0o755); err != nil {
25			t.Fatal(err)
26		}
27		defPath := filepath.Join(t.TempDir(), "def.json")
28		if err := os.WriteFile(defPath, []byte(def), 0o644); err != nil {
29			t.Fatal(err)
30		}
31		s, err := Open(absDir)
32		if err != nil {
33			t.Fatalf("seed Open: %v", err)
34		}
35		if _, err := s.CreateCircuit(Circuit{Name: "c", Version: 1, Constraints: 1,
36			PublicInputs: 1, PrivateInputs: 1, Description: desc}); err != nil {
37			t.Fatal(err)
38		}
39		if _, err := s.ImportConstraints("c", 1, defPath); err != nil {
40			t.Fatal(err)
41		}
42		if _, err := s.FreezeCircuit("c", 1); err != nil {
43			t.Fatal(err)
44		}
45		if _, err := s.RecordSetup("c", 1); err != nil {
46			t.Fatal(err)
47		}
48		a, err := s.CompileCircuit("c", 1)
49		if err != nil {
50			t.Fatal(err)
51		}
52		if err := s.Close(); err != nil {
53			t.Fatal(err)
54		}
55		return a
56	}
57	
58	// With a bench-data in each of two working directories, a store opened
59	// against the relative name in the first keeps operating on the first after
60	// the process moves to the second: reads return the first record, writes
61	// land in the first directory, and compiled-artifact / job bindings resolve
62	// against the first directory's frozen version even though the second holds
63	// the same name and version with a different (different-modulus) artifact.
64	func TestStorePinsRelativeDataDirectoryAcrossChdir(t *testing.T) {
65		root := t.TempDir()
66		w1 := filepath.Join(root, "w1")
67		w2 := filepath.Join(root, "w2")
68		art1 := seedBenchData(t, filepath.Join(w1, "bench-data"), "first description", validDef)
69		art2 := seedBenchData(t, filepath.Join(w2, "bench-data"), "second description", altDef)
70		if art1.Hash == art2.Hash {
71			t.Fatal("seed artifacts must differ so a swapped directory is observable")
72		}
73		w2DataBefore, err := os.ReadFile(filepath.Join(w2, "bench-data", dirDataFile))
74		if err != nil {
75			t.Fatal(err)
76		}
77	
78		t.Chdir(w1)
79		s, err := Open("bench-data")
80		if err != nil {
81			t.Fatalf("Open relative: %v", err)
82		}
83		t.Cleanup(func() { s.Close() })
84	
85		if got := s.Dir(); got != filepath.Join(w1, "bench-data") {
86			t.Fatalf("Dir = %q, want %q", got, filepath.Join(w1, "bench-data"))
87		}
88	
89		// Move the process to the second working directory; the store must not
90		// follow.
91		t.Chdir(w2)
92	
93		if got := s.Dir(); got != filepath.Join(w1, "bench-data") {
94			t.Fatalf("Dir after chdir = %q, want %q", got, filepath.Join(w1, "bench-data"))
95		}
96		c, err := s.GetCircuit("c", 1)
97		if err != nil {
98			t.Fatalf("GetCircuit: %v", err)
99		}
100		if c.Description != "first description" {
101			t.Fatalf("read %q from the second directory; want the first directory's record", c.Description)
102		}
103	
104		// Recompiling after the chdir must return the first directory's frozen
105		// artifact hash, not the same-named version's artifact in the second.
106		a, err := s.CompileCircuit("c", 1)
107		if err != nil {
108			t.Fatalf("CompileCircuit: %v", err)
109		}
110		if a.Hash != art1.Hash {
111			t.Fatalf("artifact hash %q belongs to the second directory; want %q", a.Hash, art1.Hash)
112		}
113		if a.Hash == art2.Hash {
114			t.Fatal("pinned store returned the second directory's artifact")
115		}
116		gotArt, err := s.GetArtifact("c", 1)
117		if err != nil || gotArt.Hash != art1.Hash {
118			t.Fatalf("GetArtifact = %+v, %v", gotArt, err)
119		}
120	
121		// A job bound to that hash registers against the first directory's
122		// version and is queryable from the same store afterwards.
123		job, err := s.SubmitJob(Job{ID: "j1", Circuit: "c", Version: 1, Kind: "prove", Attempt: 1, CompiledHash: art1.Hash})
124		if err != nil {
125			t.Fatalf("SubmitJob: %v", err)
126		}
127		if job.CompiledHash != art1.Hash {
128			t.Fatalf("bound hash %q, want %q", job.CompiledHash, art1.Hash)
129		}
130		if _, err := s.GetJob("j1"); err != nil {
131			t.Fatalf("GetJob: %v", err)
132		}
133	
134		// A draft-only update round-trips through the first directory.
135		if _, err := s.CreateCircuit(Circuit{Name: "draft", Version: 1, Constraints: 2, Description: "d"}); err != nil {
136			t.Fatal(err)
137		}
138		if _, err := s.UpdateCircuit(Circuit{Name: "draft", Version: 1, Constraints: 3, Description: "edited in first"}); err != nil {
139			t.Fatal(err)
140		}
141	
142		w1Data, err := os.ReadFile(filepath.Join(w1, "bench-data", dirDataFile))
143		if err != nil {
144			t.Fatal(err)
145		}
146		if !strings.Contains(string(w1Data), "first description") || !strings.Contains(string(w1Data), "edited in first") || !strings.Contains(string(w1Data), art1.Hash) || !strings.Contains(string(w1Data), `"j1"`) {
147			t.Fatalf("first directory data.json missing pinned writes:\n%s", w1Data)
148		}
149		w2DataAfter, err := os.ReadFile(filepath.Join(w2, "bench-data", dirDataFile))
150		if err != nil {
151			t.Fatal(err)
152		}
153		if string(w2DataAfter) != string(w2DataBefore) {
154			t.Fatalf("second directory data.json changed while operating the first store:\nbefore:\n%s\nafter:\n%s", w2DataBefore, w2DataAfter)
155		}
156	}
