158	// When the new working directory has no bench-data, the store keeps reading
159	// and saving the original directory: no not-found errors, no save failures,
160	// and no second bench-data created in the new working directory.
161	func TestStoreStaysOnOriginalWhenNewCwdHasNoDataDir(t *testing.T) {
162		root := t.TempDir()
163		w1 := filepath.Join(root, "w1")
164		w2 := filepath.Join(root, "w2")
165		if err := os.MkdirAll(w2, 0o755); err != nil {
166			t.Fatal(err)
167		}
168		seedBenchData(t, filepath.Join(w1, "bench-data"), "first description", validDef)
169	
170		t.Chdir(w1)
171		s, err := Open("bench-data")
172		if err != nil {
173			t.Fatalf("Open relative: %v", err)
174		}
175		t.Cleanup(func() { s.Close() })
176		t.Chdir(w2)
177	
178		if _, err := s.GetCircuit("c", 1); err != nil {
179			t.Fatalf("reading the original circuit after moving to an empty cwd: %v", err)
180		}
181		if _, err := s.CreateCircuit(Circuit{Name: "late", Version: 1, Constraints: 1, Description: "saved in first"}); err != nil {
182			t.Fatalf("saving after moving to an empty cwd: %v", err)
183		}
184		if _, err := os.Stat(filepath.Join(w2, "bench-data")); !errors.Is(err, os.ErrNotExist) {
185			t.Fatalf("a bench-data appeared in the new cwd: %v", err)
186		}
187		data, err := os.ReadFile(filepath.Join(w1, "bench-data", dirDataFile))
188		if err != nil {
189			t.Fatal(err)
190		}
191		if !strings.Contains(string(data), "saved in first") {
192			t.Fatalf("write did not land in the original directory:\n%s", data)
193		}
194	}
195	
196	// A relative directory that does not exist at Open time is still created,
197	// and the created directory is pinned the same way.
198	func TestStoreCreatesRelativeDirThenPinsIt(t *testing.T) {
199		root := t.TempDir()
200		w1 := filepath.Join(root, "w1")
201		w2 := filepath.Join(root, "w2")
202		if err := os.MkdirAll(w1, 0o755); err != nil {
203			t.Fatal(err)
204		}
205		if err := os.MkdirAll(w2, 0o755); err != nil {
206			t.Fatal(err)
207		}
208	
209		t.Chdir(w1)
210		s, err := Open("fresh-data")
211		if err != nil {
212			t.Fatalf("Open missing relative dir: %v", err)
213		}
214		t.Cleanup(func() { s.Close() })
215		if fi, err := os.Stat(filepath.Join(w1, "fresh-data")); err != nil || !fi.IsDir() {
216			t.Fatalf("Open did not create the relative directory: %v", err)
217		}
218	
219		t.Chdir(w2)
220		if _, err := s.CreateCircuit(Circuit{Name: "c", Version: 1, Constraints: 1, Description: "only here"}); err != nil {
221			t.Fatalf("write after chdir: %v", err)
222		}
223		if _, err := os.Stat(filepath.Join(w2, "fresh-data")); !errors.Is(err, os.ErrNotExist) {
224			t.Fatal("a fresh-data appeared in the new cwd")
225		}
226		if got, err := s.GetCircuit("c", 1); err != nil || got.Description != "only here" {
227			t.Fatalf("readback after chdir = %+v, %v", got, err)
228		}
229	}
230	
231	// Corruption of the originally opened file is still detected after a chdir:
232	// the next operation fails with ErrDataCorrupt, leaves the corrupt file in
233	// place, and never falls back to the intact file in the new working
234	// directory nor overwrites the damage with an empty state.
235	func TestStoreCorruptionOfOriginalNotBypassedByChdir(t *testing.T) {
236		root := t.TempDir()
237		w1 := filepath.Join(root, "w1")
238		w2 := filepath.Join(root, "w2")
239		seedBenchData(t, filepath.Join(w1, "bench-data"), "first description", validDef)
240		seedBenchData(t, filepath.Join(w2, "bench-data"), "second description", altDef)
241	
242		t.Chdir(w1)
243		s, err := Open("bench-data")
244		if err != nil {
245			t.Fatalf("Open relative: %v", err)
246		}
247		t.Cleanup(func() { s.Close() })
248		t.Chdir(w2)
249	
250		origFile := filepath.Join(w1, "bench-data", dirDataFile)
251		corrupt := []byte(`{"format":1, broken`)
252		if err := os.WriteFile(origFile, corrupt, 0o644); err != nil {
253			t.Fatal(err)
254		}
255		if _, err := s.GetCircuit("c", 1); !errors.Is(err, ErrDataCorrupt) {
256			t.Fatalf("want ErrDataCorrupt from the damaged original file, got %v", err)
257		}
258		left, err := os.ReadFile(origFile)
259		if err != nil {
260			t.Fatal(err)
261		}
262		if string(left) != string(corrupt) {
263			t.Fatalf("damaged original file was overwritten:\n%s", left)
264		}
265		w2Data, err := os.ReadFile(filepath.Join(w2, "bench-data", dirDataFile))
266		if err != nil {
267			t.Fatal(err)
268		}
269		if !strings.Contains(string(w2Data), "second description") {
270			t.Fatal("the new cwd's intact data file was touched")
271		}
272	}
273	
274	// Constraint definition and input files keep being resolved against the
275	// working directory at call time, not against the pinned data directory's
276	// location: the store's pinning must not drag them along.
277	func TestStoreRelativeDefinitionAndInputFollowCallCwd(t *testing.T) {
278		root := t.TempDir()
279		w1 := filepath.Join(root, "w1")
280		w2 := filepath.Join(root, "w2")
281		seedBenchData(t, filepath.Join(w1, "bench-data"), "first description", validDef)
282		if err := os.MkdirAll(w2, 0o755); err != nil {
283			t.Fatal(err)
284		}
285	
286		// In the first directory a same-named relative file is unusable junk.
287		if err := os.WriteFile(filepath.Join(w1, "def.json"), []byte(`{not json`), 0o644); err != nil {
288			t.Fatal(err)
289		}
290		// In the second directory the same relative name holds a valid document.
291		if err := os.WriteFile(filepath.Join(w2, "def.json"), []byte(validDef), 0o644); err != nil {
292			t.Fatal(err)
293		}
294		// And a witness file resolvable only from the second directory.
295		if err := os.WriteFile(filepath.Join(w2, "witness.json"),
296			[]byte(`{"public":["2"],"private":["3"]}`), 0o644); err != nil {
297			t.Fatal(err)
298		}
299	
300		t.Chdir(w1)
301		s, err := Open("bench-data")
302		if err != nil {
303			t.Fatalf("Open relative: %v", err)
304		}
305		t.Cleanup(func() { s.Close() })
306		if _, err := s.CreateCircuit(Circuit{Name: "d", Version: 1, Constraints: 1,
307			PublicInputs: 1, PrivateInputs: 1, Description: "d"}); err != nil {
308			t.Fatal(err)
309		}
310	
311		// From the first cwd the relative definition must resolve to its junk
312		// file (proving paths follow the call-time cwd in both directions).
313		if _, err := s.ImportConstraints("d", 1, "def.json"); err == nil {
314			t.Fatal("relative def.json in the first cwd should have been the junk file")
315		}
316	
317		t.Chdir(w2)
318		if _, err := s.ImportConstraints("d", 1, "def.json"); err != nil {
319			t.Fatalf("relative def.json should resolve in the new cwd: %v", err)
320		}
321		if _, err := s.FreezeCircuit("d", 1); err != nil {
322			t.Fatal(err)
323		}
324		a, err := s.CompileCircuit("d", 1)
325		if err != nil {
326			t.Fatal(err)
327		}
328		res, err := s.CheckInputFile("d", 1, a.Hash, "witness.json")
329		if err != nil {
330			t.Fatalf("relative witness.json should resolve in the new cwd: %v", err)
331		}
332		if !res.Satisfied {
333			t.Fatalf("witness from the new cwd not evaluated: %+v", res)
334		}
335	}
