18	// on-disk layout inside the data directory:
19	//
20	//	data.json    – the committed state (JSON envelope, atomically replaced)
21	//	data.json.tmp– staging file for the next commit (rename(2) target)
22	//	lock         – flock file serializing concurrent processes
23	//
24	// The envelope carries an explicit format version: files written by an
25	// incompatible future build are refused rather than silently migrated or
26	// overwritten.
27	const (
28		dirDataFile = "data.json"
29		dirTmpFile  = "data.json.tmp"
30		dirLockFile = "lock"
31	
32		// FormatVersion is the on-disk format this build writes and accepts.
