71	func (e *envelope) UnmarshalJSON(raw []byte) error {
72		// Reject repeated keys before decoding: encoding/json silently keeps the
73		// last value of a duplicate. The walk is layered so a repeated field is
74		// attributed to the record it belongs to (a duplicate "frozen" inside
75		// circuit #3, not a generic envelope complaint).
76		if err := scanEnvelopeDuplicates(raw); err != nil {
77			return err
78		}
79		var wire envelopeWire
80		if err := json.Unmarshal(raw, &wire); err != nil {
81			var se StoreError
82			if errors.As(err, &se) && se.Kind == ErrDataCorrupt.Kind {
83				return err // an inner record decoder already named the problem
84			}
85			return corruptf("data file envelope is not valid JSON: %v", err)
86		}
87		e.Format = wire.Format
88		e.Setups = wire.Setups
89		e.Jobs = wire.Jobs
90		e.Artifacts = wire.Artifacts
91		if wire.Circuits == nil {
92			e.Circuits = nil
93		} else {
94			e.Circuits = make([]persistCircuit, len(wire.Circuits))
95		}
96		for i, craw := range wire.Circuits {
97			var record persistCircuit
98			if err := json.Unmarshal(craw, &record); err != nil {
99				var se StoreError
100				if errors.As(err, &se) {
101					// Re-tag as one corruption error carrying the record index,
102					// so the detail survives errors.As unwrapping in loadLocked.
103					return StoreError{Kind: ErrDataCorrupt.Kind,
104						Detail: fmt.Sprintf("circuit record #%d: %s", i+1, se.Detail)}
105				}
106				return corruptf("circuit record #%d: %v", i+1, err)
107			}
108			e.Circuits[i] = record
109		}
110		return nil
111	}
112	
113	// envelopeTopFields are the five fields an envelope may carry. Their
114	// canonical (standard lowercase) spellings are the wire tags on envelope and
115	// envelopeWire; JSON keys are tokenized after unescaping.
116	var envelopeTopFields = []string{"format", "circuits", "setups", "jobs", "artifacts"}
117	
118	// canonicalEnvelopeField reports the standard lowercase name of one of the
119	// five envelope fields when key names it under any ASCII letter-case spelling
120	// ("format", "FORMAT", "FoRmAt", …). Keys are already JSON-unescaped by the
121	// tokenizer, so an escaped spelling of any such form lands here too. A
122	// non-canonical key (different length or a mismatching byte, including
123	// non-ASCII lookalikes and unknown fields such as "CIRCUIT") returns "".
124	func canonicalEnvelopeField(key string) string {
125		for _, field := range envelopeTopFields {
126			if len(key) != len(field) {
127				continue
128			}
129			i := 0
130			for i < len(key) {
131				c := key[i]
132				if c >= 'A' && c <= 'Z' {
133					c += 'a' - 'A'
134				}
135				if c != field[i] {
136					break
137				}
138				i++
139			}
140			if i == len(field) {
141				return field
142			}
143		}
144		return ""
145	}
146	
147	// envelopeFieldLookalike reports the standard lowercase name of one of the
148	// five envelope fields when key names it under a spelling encoding/json's
149	// struct-tag matching would fold onto the field but which is not an accepted
150	// ASCII letter-case spelling (canonicalEnvelopeField reports those). Tag
151	// matching folds with the Unicode simple case-folding rules
152	// (strings.EqualFold), so "circuitſ" (U+017F long s, written directly or as
153	// the JSON escape u017f — keys arrive here already unescaped) names the
154	// circuits field exactly like "circuits", even standing alone. Such a
155	// lookalike is damage whatever its value: a later "circuitſ": [] would
156	// otherwise override a populated circuits array through last-value-wins and
157	// the records would vanish on the next commit. A key that does not fold onto
158	// any known field — an unrelated unknown name such as "note", or "cİrcuits"
159	// with U+0130 dotted capital I, which does not fold — returns "" and keeps
160	// the ordinary unknown-member handling.
161	func envelopeFieldLookalike(key string) string {
162		if canonicalEnvelopeField(key) != "" {
163			return "" // an accepted ASCII spelling, not a lookalike
164		}
165		for _, field := range envelopeTopFields {
166			if strings.EqualFold(key, field) {
167				return field
168			}
169		}
170		return ""
171	}
172	
173	// scanEnvelopeDuplicates tokenizes the committed envelope and rejects every
174	// repeated object key. The five known top-level fields are identified case-
175	// insensitively: two spellings that differ only in ASCII letter case (both
176	// keys already JSON-unescaped at this point) are the same field, in whatever
177	// order they appear and whether or not their values agree, so a later
178	// "CIRCUITS" or "FORMAT" can never override an earlier one through encoding/
179	// json's last-value-wins struct matching. Such a pair is reported as a
180	// duplicated top-level field named by its standard lowercase spelling.
181	//
182	// A non-ASCII spelling that folds onto a known field but is not an ASCII case
183	// variant ("circuitſ", "setupſ", "jobſ", "artifactſ" with U+017F long s,
184	// directly written or ſ-escaped) is rejected outright as data corruption:
185	// encoding/json would match it onto the field, so ignoring it as unknown
186	// could let its value replace the real one (an empty array hiding every
187	// record), and accepting it would let the records vanish on the next commit.
188	// The rule holds for the lookalike appearing alone — value a legal record, an
189	// empty array or null alike — and for it appearing beside the canonical
190	// spelling or an ASCII case variant, in either order and whether the values
191	// agree. The error names both the standard field and the actual spelling.
192	//
193	// Circuit and job records are scanned one record at a time — their own
194	// top-level fields are checked here (with the record's 1-based index, or the
195	// job's id, reported) by scanCircuitArrayDuplicates and the shared job reader
196	// scanJobArray in job_record.go, while a nested value such as a constraint
197	// definition or an unknown job member's object is skipped and left to its own
198	// strict decoder. Every other envelope member is scanned recursively so a
199	// duplicated key anywhere in committed data fails the read instead of
200	// silently resolving to its last value.
201	func scanEnvelopeDuplicates(raw []byte) error {
202		dec := json.NewDecoder(bytes.NewReader(bytes.TrimSpace(raw)))
203		dec.UseNumber()
204		open, err := dec.Token()
205		if err != nil || open != json.Delim('{') {
206			return corruptf("data file envelope must be a JSON object")
207		}
208		// Exact spellings retain the pre-existing check for unknown keys;
209		// canonical names remember a known field's first occurrence regardless
210		// of the case it was written in.
211		seenTop := make(map[string]bool)
212		seenCanonical := make(map[string]bool)
213		for dec.More() {
214			keyTok, err := dec.Token()
215			if err != nil {
216				return corruptf("data file envelope is not valid JSON: %v", err)
217			}
218			key, ok := keyTok.(string)
219			if !ok {
220				return corruptf("data file envelope is not valid JSON")
221			}
222			// Reject a non-ASCII spelling that encoding/json's Unicode-folded tag
223			// matching would read as a known field ("circuitſ" with long s,
224			// directly written or ſ-escaped) before anything else. It is damage
225			// even on its own and whatever its value — a legal record, an empty
226			// array or null — and whether it precedes or follows the canonical or
227			// an ASCII case-variant spelling: the read may neither ignore it as an
228			// unknown member nor choose one of the values and carry on.
229			if canonical := envelopeFieldLookalike(key); canonical != "" {
230				return corruptf("data file envelope carries top-level field %q under non-ASCII spelling %q; such a lookalike spelling is data corruption",
231					canonical, key)
232			}
233			if canonical := canonicalEnvelopeField(key); canonical != "" {
234				if seenCanonical[canonical] {
235					if key == canonical {
236						return corruptf("data file envelope contains duplicate top-level field %q", canonical)
237					}
238					return corruptf("data file envelope contains duplicate top-level field %q (also present as %q)",
239						canonical, key)
240				}
241				seenCanonical[canonical] = true
242				if canonical == "circuits" {
243					if err := scanCircuitArrayDuplicates(dec); err != nil {
244						return err
245					}
246					continue
247				}
248				if canonical == "jobs" {
249					if err := scanJobArray(dec); err != nil {
250						return err
251					}
252					continue
253				}
254				if err := skipValueWithDupKeys(dec, "data file envelope field "+strconv.Quote(canonical)); err != nil {
255					return err
256				}
257				continue
258			}
259			if seenTop[key] {
260				return corruptf("data file envelope contains duplicate field %q", key)
261			}
262			seenTop[key] = true
263			if err := skipValueWithDupKeys(dec, "data file envelope field "+strconv.Quote(key)); err != nil {
264				return err
265			}
266		}
267		if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
268			return corruptf("data file envelope is not valid JSON")
269		}
270		if _, err := dec.Token(); err != io.EOF {
271			return corruptf("data file envelope is not valid JSON: trailing data after the object")
272		}
273		return nil
274	}
275	
276	// scanCircuitArrayDuplicates consumes one "circuits" value positioned at its
277	// opening bracket and checks only each record's own top-level keys. The
278	// enclosing key may carry any case spelling, but the field it names is the
279	// canonical "circuits". A null array stays the pre-existing "no records"
280	// reading.
281	func scanCircuitArrayDuplicates(dec *json.Decoder) error {
282		tok, err := dec.Token()
283		if err != nil {
284			return corruptf("data file envelope field \"circuits\" is not valid JSON: %v", err)
285		}
286		if tok == nil { // null: json.Unmarshal would produce no records
287			return nil
288		}
289		if tok != json.Delim('[') {
290			return corruptf("data file envelope field \"circuits\" must be an array")
291		}
292		index := 0
293		for dec.More() {
294			index++
295			what := fmt.Sprintf("circuit record #%d", index)
296			open, err := dec.Token()
297			if err != nil {
298				return corruptf("%s is not valid JSON: %v", what, err)
299			}
300			if open == nil {
301				return corruptf("%s must be a JSON object, not null", what)
302			}
303			if open != json.Delim('{') {
304				return corruptf("%s must be a JSON object", what)
305			}
306			seen := make(map[string]bool)
307			for dec.More() {
308				keyTok, err := dec.Token()
309				if err != nil {
310					return corruptf("%s is not valid JSON: %v", what, err)
311				}
312				key, ok := keyTok.(string)
313				if !ok {
314					return corruptf("%s is not valid JSON", what)
315				}
316				if seen[key] {
317					return corruptf("%s contains duplicate field %q", what, key)
318				}
319				seen[key] = true
320				// Skip the whole value without descending: nested objects
321				// (definition) own their own strict duplicate checks.
322				var skip json.RawMessage
323				if err := dec.Decode(&skip); err != nil {
324					return corruptf("%s is not valid JSON: %v", what, err)
325				}
326			}
327			if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
328				return corruptf("%s is not valid JSON", what)
329			}
330		}
331		if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim(']') {
332			return corruptf("data file envelope field \"circuits\" is not valid JSON")
333		}
334		return nil
335	}
336	
337	// skipValueWithDupKeys consumes one JSON value positioned at its first token,
338	// recursively rejecting duplicate object keys.
339	func skipValueWithDupKeys(dec *json.Decoder, what string) error {
340		tok, err := dec.Token()
341		if err != nil {
342			return corruptf("%s is not valid JSON: %v", what, err)
343		}
344		delim, ok := tok.(json.Delim)
345		if !ok {
346			return nil // scalar (including null)
347		}
348		switch delim {
349		case '{':
350			seen := make(map[string]bool)
351			for dec.More() {
352				keyTok, err := dec.Token()
353				if err != nil {
354					return corruptf("%s is not valid JSON: %v", what, err)
355				}
356				key, ok := keyTok.(string)
357				if !ok {
358					return corruptf("%s is not valid JSON", what)
359				}
360				if seen[key] {
361					return corruptf("%s contains duplicate field %q", what, key)
362				}
363				seen[key] = true
364				if err := skipValueWithDupKeys(dec, what+" "+strconv.Quote(key)); err != nil {
365					return err
366				}
367			}
368			if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
369				return corruptf("%s is not valid JSON", what)
370			}
371		case '[':
372			index := 0
373			for dec.More() {
374				index++
375				if err := skipValueWithDupKeys(dec, fmt.Sprintf("%s element #%d", what, index)); err != nil {
376					return err
377				}
378			}
379			if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim(']') {
380				return corruptf("%s is not valid JSON", what)
381			}
382		}
383		return nil
384	}
385	
386	type persistTerm struct {
387		Wire  int    `json:"wire"`
388		Coeff string `json:"coeff"`
389	}
390	
391	type persistConstraint struct {
392		A []persistTerm `json:"a"`
393		B []persistTerm `json:"b"`
394		C []persistTerm `json:"c"`
395	}
396	
397	// persistDefinition is the canonical, already-validated constraint set bound
398	// to one circuit version. The public/private partition is owned by the
399	// circuit record and is deliberately not duplicated here, so it can never
400	// drift from the declared counts.
401	type persistDefinition struct {
402		Modulus     string              `json:"modulus"`
403		Constraints []persistConstraint `json:"constraints"`
404	}
405	
406	// persistArtifact is a compiled artifact: the version's identity and
407	// constraint count bound to its recomputable SHA-256 hash.
408	type persistArtifact struct {
409		Name        string `json:"name"`
410		Version     int    `json:"version"`
411		Modulus     int64  `json:"modulus"`
412		Constraints int    `json:"constraints"`
413		Hash        string `json:"hash"`
414	}
415	
416	type persistCircuit struct {
417		Name          string             `json:"name"`
418		Version       int                `json:"version"`
419		Constraints   int                `json:"constraints"`
420		PublicInputs  int                `json:"public_inputs"`
421		PrivateInputs int                `json:"private_inputs"`
422		Frozen        bool               `json:"frozen"`
423		Description   string             `json:"description"`
424		Definition    *persistDefinition `json:"definition,omitempty"`
425	}
426	
427	// Strict decoding of committed circuit records.
428	//
429	// A circuit record in data.json must name each of name, version, constraints,
430	// public_inputs, private_inputs, frozen and description exactly once, with
431	// the exact JSON type the writer emits (string / integer / integer / integer
432	// / integer / boolean / string). A missing key, a null, a wrong type or a
433	// repeated key is data corruption and refuses the whole directory read: a
434	// missing or null frozen flag must not silently read as false (turning a
435	// frozen version back into an editable draft), and a repeated key must not
436	// resolve to its last value. An explicit 0, false or "" is an ordinary value
437	// and stays legal. The definition member remains the one optional field: it
438	// may be absent or null (the legacy counts-only state); when present it goes
439	// through the strict persistDefinition decoder.
440	//
441	// The name field carries one rule beyond shape: its raw JSON string token
442	// must denote its value exactly — valid UTF-8 in the literal portions and no
443	// unpaired \uXXXX surrogate escapes (checkStoredStringEncoding). Both damage
444	// shapes decode to U+FFFD replacement characters under encoding/json, which
445	// would rename the circuit on read; they are data corruption, and the whole
446	// directory read is refused. Only the name is judged this way; every other
447	// field keeps the ordinary decoding rules.
448	//
449	// Only shape is judged here. The domain rules (non-blank name, positive
450	// version and constraint count, non-negative input counts) keep being
451	// re-checked by validateEnvelope.
452	
453	var persistCircuitFields = []string{
454		"name", "version", "constraints", "public_inputs", "private_inputs",
455		"frozen", "description", "definition",
456	}
