555	// strictCircuitObject decodes one committed circuit record's own member map,
556	// demanding a JSON object with exactly the known top-level fields once.
557	func strictCircuitObject(raw []byte, what string) (map[string]json.RawMessage, error) {
558		return strictObjectMembers(raw, what, persistCircuitFields)
559	}
560	
561	// checkStoredStringEncoding enforces an identity field's exact-readback rule
562	// on the raw JSON string token of a committed value (a circuit record's name,
563	// a job record's id). The string has already been decoded by the strict
564	// member read, so the token is known to be one complete, well-formed JSON
565	// string; this walk judges only what that decode silently repairs:
566	//
567	//   - invalid UTF-8 bytes in the literal (unescaped) portions — a lone
568	//     continuation byte, a truncated multi-byte character, an overlong
569	//     form — which encoding/json rewrites to U+FFFD, and
570	//   - \uXXXX escapes forming an unpaired surrogate — a high surrogate not
571	//     immediately followed by its low-surrogate escape, or a low surrogate
572	//     standing alone — which are rewritten to U+FFFD the same way.
573	//
574	// Both would make the record read back under a different value than the bytes
575	// on disk carry, so the record is data corruption rather than a value that
576	// legitimately decodes to a replacement character it never had. noun is the
577	// word naming the value in diagnostics ("committed name" / "committed job
578	// id"); what locates the record and field, e.g.
579	// `stored circuit record field "name"` or `stored job record "j1" field
580	// "id"`. A legal surrogate pair decodes to its astral character, an actually
581	// committed "�" (written directly or as a U+FFFD escape) is an ordinary
582	// value, and the literal six characters "\uD800" — written with an escaped
583	// backslash — carry no escape at all: all three keep their exact value.
584	func checkStoredStringEncoding(raw json.RawMessage, what, noun string) error {
585		token := bytes.TrimSpace(raw)
586		// The token is a complete JSON string (the strict string read above
587		// succeeded), so every escape is well-formed and the walk stays in
588		// bounds; only the replacement-prone content is judged.
589		for i := 1; i < len(token)-1; {
590			c := token[i]
591			if c == '\\' {
592				if token[i+1] != 'u' {
593					i += 2 // a simple escape: \" \\ \/ \b \f \n \r \t
594					continue
595				}
596				code, _ := strconv.ParseUint(string(token[i+2:i+6]), 16, 32)
597				switch {
598				case code >= 0xD800 && code <= 0xDBFF:
599					// A high surrogate is whole only when its low-surrogate
600					// escape follows immediately.
601					if i+12 <= len(token) && token[i+6] == '\\' && token[i+7] == 'u' {
602						lo, _ := strconv.ParseUint(string(token[i+8:i+12]), 16, 32)
603						if lo >= 0xDC00 && lo <= 0xDFFF {
604							i += 12
605							continue
606						}
607					}
608					return corruptf("%s contains an unpaired high surrogate escape (\\u%04X); the %s would not read back unchanged", what, code, noun)
609				case code >= 0xDC00 && code <= 0xDFFF:
610					return corruptf("%s contains an unpaired low surrogate escape (\\u%04X); the %s would not read back unchanged", what, code, noun)
611				}
612				i += 6
613				continue
614			}
615			if c < utf8.RuneSelf {
616				i++
617				continue
618			}
619			r, size := utf8.DecodeRune(token[i:])
620			if r == utf8.RuneError && size == 1 {
621				return corruptf("%s contains invalid UTF-8 bytes; the %s would not read back unchanged", what, noun)
622			}
623			i += size
624		}
625		return nil
626	}
