628	// strictObjectMembers decodes one committed record's own member map,
629	// demanding a JSON object without repeated keys. A non-nil allowed list
630	// restricts which keys may appear; nil allows any key. It scans only the
631	// record's own level: the envelope scanner already attributes a duplicated
632	// top-level key to this record, and nested values such as the constraint
633	// definition own their (more precise) strict decoders. Keys are compared
634	// after JSON unescaping, so a field repeated through a \uXXXX spelling is
635	// still a duplicate, even when both values are identical.
636	func strictObjectMembers(raw []byte, what string, allowedFields []string) (map[string]json.RawMessage, error) {
637		trimmed := bytes.TrimSpace(raw)
638		if len(trimmed) == 0 || trimmed[0] != '{' {
639			return nil, corruptf("%s must be a JSON object", what)
640		}
641		dec := json.NewDecoder(bytes.NewReader(trimmed))
642		dec.UseNumber()
643		open, err := dec.Token()
644		if err != nil || open != json.Delim('{') {
645			return nil, corruptf("%s must be a JSON object", what)
646		}
647		var allowed map[string]bool
648		if allowedFields != nil {
649			allowed = make(map[string]bool, len(allowedFields))
650			for _, f := range allowedFields {
651				allowed[f] = true
652			}
653		}
654		members := make(map[string]json.RawMessage)
655		for dec.More() {
656			keyTok, err := dec.Token()
657			if err != nil {
658				return nil, corruptf("%s is not valid JSON: %v", what, err)
659			}
660			key, ok := keyTok.(string)
661			if !ok {
662				return nil, corruptf("%s is not valid JSON", what)
663			}
664			if allowed != nil && !allowed[key] {
665				return nil, corruptf("%s has unknown field %q", what, key)
666			}
667			if _, repeated := members[key]; repeated {
668				return nil, corruptf("%s contains duplicate field %q", what, key)
669			}
670			var value json.RawMessage
671			if err := dec.Decode(&value); err != nil {
672				return nil, corruptf("%s is not valid JSON: %v", what, err)
673			}
674			members[key] = value
675		}
676		if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
677			return nil, corruptf("%s is not valid JSON", what)
678		}
679		if _, err := dec.Token(); err != io.EOF {
680			return nil, corruptf("%s is not valid JSON: trailing data after the object", what)
681		}
682		return members, nil
683	}
