690	// Store is a persistent workbench backed by one local data directory.
691	//
692	// All operations are safe for concurrent use by multiple goroutines and by
693	// several processes pointed at the same directory: an in-process mutex plus a
694	// process-shared flock serialize commits, and every commit is an atomic
695	// temp-file/fsync/rename replacement. Open the directory with Open and call
696	// Close when done.
697	type Store struct {
698		dir  string
699		mu   sync.Mutex
700		lock *os.File
701	
702		data envelope
703	}
704	
705	// Open opens (creating if needed) the workbench data in dir. If the
706	// directory does not exist it is created. Existing committed data is loaded
707	// and fully validated before Open returns; on a corrupt, truncated or
708	// unsupported-format file Open returns an error wrapping ErrDataCorrupt and
709	// leaves every file in the directory untouched.
710	//
711	// dir is resolved against the process's current working directory at Open
712	// time and pinned for the store's lifetime: a relative path such as
713	// "bench-data" names one fixed directory from the moment Open succeeds, and
714	// later working-directory changes never redirect the store's reads, writes,
715	// lock or Dir to another location. Paths to constraint definitions and input
716	// files passed to individual operations are not pinned this way — they keep
717	// being resolved against the caller's working directory at call time.
718	func Open(dir string) (*Store, error) {
719		if dir == "" {
720			return nil, invalidf("data directory must not be empty")
721		}
722		// Pin the location now: a relative path would otherwise be re-resolved
723		// against the process working directory on every later file access, so a
724		// chdir after Open could silently move the store onto a different
725		// bench-data. Abs (not EvalSymlinks) so a not-yet-existing directory can
726		// still be created below.
727		absDir, err := filepath.Abs(dir)
728		if err != nil {
729			return nil, fmt.Errorf("cannot resolve data directory %q: %w", dir, err)
730		}
731		dir = absDir
732		if err := os.MkdirAll(dir, 0o755); err != nil {
733			return nil, fmt.Errorf("cannot create data directory %q: %w", dir, err)
734		}
735		lockPath := filepath.Join(dir, dirLockFile)
736		lock, err := os.OpenFile(lockPath, os.O_RDWR|os.O_CREATE, 0o644)
737		if err != nil {
738			return nil, fmt.Errorf("cannot open lock file in %q: %w", dir, err)
739		}
740		// Serialize against other processes while we read / validate.
741		if err := lockExclusive(lock); err != nil {
742			lock.Close()
743			return nil, fmt.Errorf("cannot lock data directory %q: %w", dir, err)
744		}
745	
746		s := &Store{dir: dir, lock: lock}
747		if err := s.loadLocked(); err != nil {
748			unlockLock(lock)
749			lock.Close()
750			return nil, err
751		}
752		// The lock is taken again per operation; holding it for the store's
753		// lifetime would forbid two open handles on one directory.
754		if err := unlockLock(lock); err != nil {
755			lock.Close()
756			return nil, fmt.Errorf("cannot release open lock on %q: %w", dir, err)
757		}
758		return s, nil
759	}
760	
761	// Close releases the directory lock. It does not discard committed data.
762	func (s *Store) Close() error {
763		s.mu.Lock()
764		defer s.mu.Unlock()
765		if s.lock == nil {
766			return nil
767		}
768		var first error
769		if err := unlockLock(s.lock); err != nil {
770			first = err
771		}
772		if err := s.lock.Close(); err != nil && first == nil {
773			first = err
774		}
775		s.lock = nil
776		return first
777	}
778	
779	// Dir reports the data directory backing the store.
780	func (s *Store) Dir() string { return s.dir }
781	
782	func (s *Store) dataPath() string { return filepath.Join(s.dir, dirDataFile) }
783	func (s *Store) tmpPath() string  { return filepath.Join(s.dir, dirTmpFile) }
784	
785	// loadLocked reads and validates the committed file. Caller must hold the
786	// exclusive flock; the in-process mutex is taken by the public Open path.
787	func (s *Store) loadLocked() error {
788		raw, err := os.ReadFile(s.dataPath())
789		if errors.Is(err, os.ErrNotExist) {
790			s.data = envelope{Format: FormatVersion}
791			return nil
792		}
793		if err != nil {
794			return fmt.Errorf("cannot read data file %q: %w", s.dataPath(), err)
795		}
796		if len(strings.TrimSpace(string(raw))) == 0 {
797			return corruptf("data file %q is empty or truncated; refusing to treat it as a new directory", s.dataPath())
798		}
799	
800		var env envelope
801		if err := json.Unmarshal(raw, &env); err != nil {
802			// Shape failures surfaced by the persisted-definition decoders are
803			// integrity failures, not JSON syntax errors; report their detail
804			// instead of the generic "not valid JSON" wording.
805			var se StoreError
806			if errors.As(err, &se) && se.Kind == ErrDataCorrupt.Kind {
807				return corruptf("data file %q failed integrity validation: %s; original file left in place", s.dataPath(), se.Detail)
808			}
809			return corruptf("data file %q is not valid JSON (%v); original file left in place", s.dataPath(), err)
810		}
811		if env.Format == 0 {
812			return corruptf("data file %q has no format version; original file left in place", s.dataPath())
813		}
814		if env.Format != FormatVersion {
815			return corruptf("data file %q uses unsupported format version %d (this build supports %d); original file left in place",
816				s.dataPath(), env.Format, FormatVersion)
817		}
818		if err := validateEnvelope(env); err != nil {
819			return corruptf("data file %q failed integrity validation: %v; original file left in place", s.dataPath(), err)
820		}
821		s.data = env
822		return nil
823	}
824	
825	// commitLocked writes the pending state atomically: temp file → fsync →
826	// rename → fsync directory. Caller must hold both the in-process mutex and
827	// the exclusive flock; all in-memory mutations must already have happened and
828	// been rule-checked, so a failure here occurs before any success is reported.
829	func (s *Store) commitLocked() error {
830		s.data.Format = FormatVersion
831		// Stable output: records are stored sorted so files are deterministic.
832		sortEnvelope(&s.data)
833	
834		payload, err := json.MarshalIndent(&s.data, "", "  ")
835		if err != nil {
836			return fmt.Errorf("cannot encode data: %w", err)
837		}
838		payload = append(payload, '\n')
839	
840		tmp := s.tmpPath()
841		f, err := os.OpenFile(tmp, os.O_RDWR|os.O_CREATE|os.O_TRUNC, 0o644)
842		if err != nil {
843			return fmt.Errorf("cannot stage write in %q: %w", s.dir, err)
844		}
845		if _, err := f.Write(payload); err != nil {
846			f.Close()
847			os.Remove(tmp)
848			return fmt.Errorf("cannot write staged data: %w", err)
849		}
850		if err := f.Sync(); err != nil {
851			f.Close()
852			os.Remove(tmp)
853			return fmt.Errorf("cannot flush staged data: %w", err)
854		}
855		if err := f.Close(); err != nil {
856			os.Remove(tmp)
857			return fmt.Errorf("cannot finish staged data: %w", err)
858		}
859		if err := os.Rename(tmp, s.dataPath()); err != nil {
860			os.Remove(tmp)
861			return fmt.Errorf("cannot commit data file: %w", err)
862		}
863		if err := syncDir(s.dir); err != nil {
864			// The rename already happened; lack of dir fsync only weakens crash
865			// durability, never correctness of what is visible now.
866			return nil
867		}
868		return nil
869	}
870	
871	// withLock runs fn under the in-process mutex and an exclusive flock, then
872	// atomically commits when fn requests it. The on-disk state is re-read after
873	// acquiring the lock, so concurrent commits from another process or another
874	// handle are always observed. Operations validate before mutating; a rejected
875	// operation (commit=false or an error) writes nothing and leaves committed
876	// state unchanged.
877	func (s *Store) withLock(fn func() (commit bool, err error)) error {
878		s.mu.Lock()
879		defer s.mu.Unlock()
880		if s.lock == nil {
881			return invalidf("store is closed")
882		}
883		if err := lockExclusive(s.lock); err != nil {
884			return fmt.Errorf("cannot lock data directory: %w", err)
885		}
886		defer unlockLock(s.lock)
887	
888		if err := s.loadLocked(); err != nil {
889			return err
890		}
891		commit, err := fn()
892		if err != nil {
893			return err
894		}
895		if !commit {
896			return nil
897		}
898		return s.commitLocked()
899	}
900	
901	// withLockRead runs fn under a shared flock over freshly reloaded state.
902	func (s *Store) withLockRead(fn func() error) error {
903		s.mu.Lock()
904		defer s.mu.Unlock()
905		if s.lock == nil {
906			return invalidf("store is closed")
907		}
908		if err := lockShared(s.lock); err != nil {
909			return fmt.Errorf("cannot lock data directory: %w", err)
910		}
911		defer unlockLock(s.lock)
912		if err := s.loadLocked(); err != nil {
913			return err
914		}
915		return fn()
916	}
