918	func sortEnvelope(env *envelope) {
919		sort.Slice(env.Circuits, func(i, j int) bool {
920			if env.Circuits[i].Name != env.Circuits[j].Name {
921				return env.Circuits[i].Name < env.Circuits[j].Name
922			}
923			return env.Circuits[i].Version < env.Circuits[j].Version
924		})
925		sort.Slice(env.Setups, func(i, j int) bool {
926			if env.Setups[i].Name != env.Setups[j].Name {
927				return env.Setups[i].Name < env.Setups[j].Name
928			}
929			return env.Setups[i].Version < env.Setups[j].Version
930		})
931		sort.Slice(env.Jobs, func(i, j int) bool { return env.Jobs[i].ID < env.Jobs[j].ID })
932		sort.Slice(env.Artifacts, func(i, j int) bool {
933			if env.Artifacts[i].Name != env.Artifacts[j].Name {
934				return env.Artifacts[i].Name < env.Artifacts[j].Name
935			}
936			return env.Artifacts[i].Version < env.Artifacts[j].Version
937		})
938	}
