// Open time. The existing prefix of the path is then resolved exactly the
// way the kernel reaches it on an open(2) — one component at a time, with
// every symlink expanded at the position where the walk meets it. In
// particular a ".." standing after a symlink pops the link's resolved target
// rather than the link's own spelling, so a/link/../x cannot be folded into
// a/x and accidentally select another data directory. Any trailing segment
// that does not exist yet (a data directory to be created by Open, or a
// not-yet-existing parent) is appended verbatim to the resolved prefix, and
// MkdirAll creates it beneath the physical parent. A dangling entry link —
// the entry itself is a symlink whose target does not exist — likewise
// resolves through the link target's spelling and is created there.
func resolveDataDir(dir string) (string, error) {
	abs, err := filepath.Abs(dir)
	if err != nil {
		return "", err
	}
	return resolveExistingPrefix(abs)
}

