	// vol is the drive/UNC volume and rest keeps its leading separator.
	anchor := string(os.PathSeparator)
	if vol != "" && len(rest) > 0 && os.IsPathSeparator(rest[0]) {
		rest = rest[1:]
	}
	var (
			components []string
			depth      int
		)
	if vol == "" {
		depth = 1 // the root separator already anchors the walk
	}
	for _, comp := range strings.Split(rest, string(os.PathSeparator)) {
		if comp == "" || comp == "." {
			continue
		}
		if comp == ".." {
			if depth > 0 {
				components = components[:len(components)-1]
				depth--
			}
			// At or above the anchor a ".." is dropped: the root is its own
			// parent on POSIX and a drive root on Windows.
			continue
		}
		components = append(components, comp)
		depth++
	}

