				for r < len(root) && os.IsPathSeparator(root[r]) {
					r++
				}
				s := r
				for r < len(root) && !os.IsPathSeparator(root[r]) {
					r++
				}
				switch root[s:r] {
				case "", ".":
				case "..":
					return "", fmt.Errorf("cannot resolve %q: %q does not exist and is followed by a parent reference", root, comp)
				default:
					dest += pathSeparator + root[s:r]
				}
			}
			return filepath.Clean(dest), nil
		}
		if fi.Mode()&os.ModeSymlink == 0 {
