// one component at a time from the anchor, every symlink expanded inline at
// the position the walk meets it, and a ".." popping the directory the walk
// is actually standing in (a link target, not the link's own spelling). The
// walk stops at the first component that cannot be Lstat'd; that component
// and the rest of the literal path are appended to the resolved physical
// prefix so MkdirAll can create the missing chain beneath it. A ".." seen
// only after such a missing component cannot be walked faithfully (the
// kernel reports ENOENT there instead of folding the literal path), so an
// error is returned — this is what keeps a trailing ".." from being
// collapsed across a symlink and selecting another data directory.
func resolveExistingPrefix(root string, linksWalked int) (string, error) {
	volLen := filepath.VolumeNameLen(root)
	pathSeparator := string(os.PathSeparator)
	if volLen < len(root) && os.IsPathSeparator(root[volLen]) {
		volLen++
	}
	vol := root[:volLen] // the anchor: "/" on Unix, drive/UNC root elsewhere
	dest := vol
	for start, end := volLen, volLen; start < len(root); start = end {
		for start < len(root) && os.IsPathSeparator(root[start]) {
			start++
		}
		end = start
		for end < len(root) && !os.IsPathSeparator(root[end]) {
			end++
		}
		if end == start {
			break
		}
		comp := root[start:end]
		if comp == "." {
			continue
		}
		if comp == ".." {
			// Pop the component the walk has actually reached. Symlinks have
			// already been expanded into dest, so this removes the target,
			// never the link spelling.
			r := -1
			for i := len(dest) - 1; i >= volLen; i-- {
				if os.IsPathSeparator(dest[i]) {
					r = i
					break
				}
			}
			if r < volLen || dest[r+1:] == ".." {
				if len(dest) > volLen {
					dest += pathSeparator
				}
				dest += ".."
			} else {
				dest = dest[:r]
			}
			continue
		}

