	if err != nil {
		t.Fatalf("Open through symlink: %v", err)
	}
	t.Cleanup(func() { s.Close() })
	if got := s.Dir(); got != d1 {
		t.Fatalf("Dir = %q, want the physical target %q", got, d1)
	}

	symlinkReplace(t, entry, d2)

	if got := s.Dir(); got != d1 {
		t.Fatalf("Dir after repoint = %q, want %q", got, d1)
	}
	c, err := s.GetCircuit("c", 1)
