// resolveDataDir turns the Open argument into the absolute physical
// directory the store will be permanently pinned to.
//
// Relative paths are anchored to the process's current working directory at
// Open time. The existing prefix of the path is then resolved exactly the
// way the kernel reaches it on an open(2) — one component at a time, with
// every symlink expanded at the position where the walk meets it. In
// particular a ".." standing after a symlink pops the link's resolved target
// rather than the link's own spelling, so a/link/../x cannot be folded into
// a/x and accidentally select another data directory. Any trailing segment
// that does not exist yet (a data directory to be created by Open, or a
// not-yet-existing parent) is appended verbatim to the resolved physical
// prefix, and MkdirAll creates it beneath that prefix. A dangling entry link
// — the entry itself is a symlink whose target does not exist — resolves
// through the link target's spelling and is created there.
func resolveDataDir(dir string) (string, error) {
	abs, err := filepath.Abs(dir)
	if err != nil {
		return "", err
	}
	return resolveExistingPrefix(abs)
}

// maxDataDirLinks bounds symlink expansion while resolving the data
// directory, matching the kernel's ELOOP guard: a link cycle must fail Open
// rather than recurse forever.
const maxDataDirLinks = 255

// resolveExistingPrefix resolves root the way a kernel path walk reaches it:
// one component at a time from the anchor, every symlink expanded inline at
// the position the walk meets it, and a ".." popping the directory the walk
// is actually standing in (a link target, not the link's own spelling). The
// walk stops at the first component that cannot be Lstat'd; that component
// and the rest of the literal path are appended to the resolved physical
// prefix so MkdirAll can create the missing chain beneath it. A ".." seen
// only after such a missing component cannot be walked faithfully (the
// kernel reports ENOENT there instead of folding the literal path), so an
// error is returned — this is what keeps a trailing ".." from being
// collapsed across a symlink and selecting another data directory.
func resolveExistingPrefix(root string) (string, error) {
	volLen := len(filepath.VolumeName(root))
	pathSeparator := string(os.PathSeparator)
	if volLen < len(root) && os.IsPathSeparator(root[volLen]) {
		volLen++
	}
	vol := root[:volLen] // the anchor: "/" on Unix, drive/UNC root elsewhere
	dest := vol
	linksWalked := 0
	for start, end := volLen, volLen; start < len(root); start = end {
		for start < len(root) && os.IsPathSeparator(root[start]) {
			start++
		}
		end = start
		for end < len(root) && !os.IsPathSeparator(root[end]) {
			end++
		}
		if end == start {
			break
		}
		comp := root[start:end]
		if comp == "." {
			continue
		}
		if comp == ".." {
			// Pop the component the walk has actually reached. Symlinks have
			// already been expanded into dest, so this removes the target,
			// never the link spelling.
			r := -1
			for i := len(dest) - 1; i >= volLen; i-- {
				if os.IsPathSeparator(dest[i]) {
					r = i
					break
				}
			}
			if r < volLen || dest[r+1:] == ".." {
				if len(dest) > volLen {
					dest += pathSeparator
				}
				dest += ".."
			} else {
				dest = dest[:r]
			}
			continue
		}

		if len(dest) > len(filepath.VolumeName(dest)) && !os.IsPathSeparator(dest[len(dest)-1]) {
			dest += pathSeparator
		}
		dest += comp

		fi, err := os.Lstat(dest)
		if err != nil {
			if !os.IsNotExist(err) {
				return "", err
			}
			// Missing tail: the kernel cannot walk past this component.
			// Append the remainder literally, refusing a remainder that
			// contains ".." (it could not be resolved against an entry that
			// does not exist), and let MkdirAll create the chain.
			for r := end; r < len(root); {
				for r < len(root) && os.IsPathSeparator(root[r]) {
					r++
				}
				s := r
				for r < len(root) && !os.IsPathSeparator(root[r]) {
					r++
				}
				switch root[s:r] {
				case "", ".":
				case "..":
					return "", fmt.Errorf("cannot resolve %q: %q does not exist and is followed by a parent reference", root, comp)
				default:
					dest += pathSeparator + root[s:r]
				}
			}
			return filepath.Clean(dest), nil
		}
		if fi.Mode()&os.ModeSymlink == 0 {
			continue
		}
		linksWalked++
		if linksWalked > maxDataDirLinks {
			return "", fmt.Errorf("cannot resolve %q: too many symlinks", root)
		}
		link, err := os.Readlink(dest)
		if err != nil {
			return "", err
		}
		// Expand the link at exactly the walk position: the still-queued
		// components (including any "..") continue from the target rather
		// than from the link's spelling.
		if filepath.IsAbs(link) {
			root = link + root[end:]
		} else {
			parent := dest[:len(dest)-(len(comp)+1)]
			if parent == "" {
				parent = pathSeparator
			}
			root = parent + pathSeparator + link + root[end:]
		}
		volLen = len(filepath.VolumeName(root))
		if volLen < len(root) && os.IsPathSeparator(root[volLen]) {
			volLen++
		}
		vol = root[:volLen]
		dest = vol
		end = volLen
	}
	return filepath.Clean(dest), nil
}

